n = len(target)

stack = []
pairs = {}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

def build(loop_char='A', pair_pattern='GC'):
    seq = [loop_char]*n
    order = sorted([k for k in pairs if k < pairs[k]])
    for idx,i in enumerate(order):
